def count_Num(n):
    """Write a python function to count numbers whose oth and nth bits are set."""
    # Count n-bit numbers (0 .. 2**n - 1) whose 0th (LSB) and (n-1)th (MSB)
    # bits are set. For n >= 2 this is 2**(n-2); n == 1 gives 1; n <= 0 gives 0.
    # This yields count_Num(2) == 1 as documented.
    if n <= 0:
        return 0
    if n == 1:
        return 1
    return 1 << (n - 2)
